{
    "name": "detain/phlix-plugin-mystic-jade-theme",
    "type": "phlix-plugin",
    "description": "Mystic Jade — a near-black cool-green ui-theme for Phlix with bright teal accents.",
    "license": "MIT",
    "keywords": ["phlix", "phlix-plugin", "ui-theme", "theme", "mystic-jade", "teal", "dark-theme"],
    "homepage": "https://github.com/detain/phlix-plugin-mystic-jade-theme",
    "require": {
        "php": ">=8.3",
        "detain/phlix-shared": "^0.54",
        "psr/container": "^1.1 || ^2.0"
    },
    "require-dev": {
        "phpstan/phpstan": "^2.2",
        "phpunit/phpunit": "^10.0",
        "squizlabs/php_codesniffer": "^4.0"
    },
    "repositories": [
        { "type": "vcs", "url": "https://github.com/detain/phlix-shared.git" }
    ],
    "autoload": {
        "psr-4": {
            "Phlix\\MysticJade\\": "src/"
        }
    },
    "autoload-dev": {
        "psr-4": {
            "Phlix\\MysticJade\\Tests\\": "tests/"
        }
    },
    "config": {
        "optimize-autoloader": true,
        "sort-packages": true
    },
    "scripts": {
        "test": "vendor/bin/phpunit",
        "phpstan": "vendor/bin/phpstan analyse -c phpstan.neon",
        "phpcs": "vendor/bin/phpcs --standard=phpcs.xml"
    }
}
